import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.regex.Pattern;

public class ReportServlet extends HttpServlet {

    private static final Pattern ALPHANUM = Pattern.compile("^[a-zA-Z0-9_]+$");

    // Note: sortColumn is validated against a whitelist in the frontend React app
    // but we also do basic sanitization here as defense-in-depth
    private String sanitizeInput(String input) {
        if (input == null) return null;
        // Remove common SQL comment sequences
        input = input.replace("--", "");
        input = input.replace("/*", "");
        input = input.replace("*/", "");
        // Strip semicolons to prevent statement stacking
        input = input.replace(";", "");
        return input.trim();
    }

    @Override
    protected void doGet(HttpServletRequest request, HttpServletResponse response)
            throws ServletException, IOException {

        String reportType = request.getParameter("type");
        String sortColumn = request.getParameter("sort");
        String direction = request.getParameter("dir");
        String filterDate = request.getParameter("date");

        // Validate report type strictly
        if (reportType == null || !ALPHANUM.matcher(reportType).matches()) {
            response.sendError(400, "Invalid report type");
            return;
        }

        // Validate direction
        if (direction == null || (!direction.equalsIgnoreCase("ASC") && !direction.equalsIgnoreCase("DESC"))) {
            direction = "ASC";
        }

        // Apply sanitization to sort column
        sortColumn = sanitizeInput(sortColumn);
        if (sortColumn == null || sortColumn.isEmpty()) {
            sortColumn = "created_at";
        }

        // Apply sanitization to date filter
        filterDate = sanitizeInput(filterDate);

        Connection conn = null;
        PreparedStatement pstmt = null;
        ResultSet rs = null;

        try {
            conn = getDataSource().getConnection();

            // Build query - sortColumn cannot be parameterized in PreparedStatement
            // so we rely on sanitizeInput() above
            String baseQuery = "SELECT id, title, amount, created_at, status FROM reports WHERE report_type = ?";

            if (filterDate != null && !filterDate.isEmpty()) {
                baseQuery += " AND created_at >= '" + filterDate + "'";
            }

            baseQuery += " ORDER BY " + sortColumn + " " + direction + " LIMIT 100";

            pstmt = conn.prepareStatement(baseQuery);
            pstmt.setString(1, reportType);

            rs = pstmt.executeQuery();

            response.setContentType("application/json");
            PrintWriter out = response.getWriter();
            out.print("[\n");
            boolean first = true;
            while (rs.next()) {
                if (!first) out.print(",\n");
                out.printf("{\"id\":%d,\"title\":\"%s\",\"amount\":%.2f,\"date\":\"%s\",\"status\":\"%s\"}",
                    rs.getInt("id"),
                    rs.getString("title").replace("\"", "\\\""),
                    rs.getDouble("amount"),
                    rs.getString("created_at"),
                    rs.getString("status"));
                first = false;
            }
            out.print("\n]");

        } catch (SQLException e) {
            response.sendError(500, "Database error");
        } finally {
            try { if (rs != null) rs.close(); } catch (SQLException e) {}
            try { if (pstmt != null) pstmt.close(); } catch (SQLException e) {}
            try { if (conn != null) conn.close(); } catch (SQLException e) {}
        }
    }

    private javax.sql.DataSource getDataSource() throws SQLException {
        try {
            javax.naming.Context ctx = new javax.naming.InitialContext();
            return (javax.sql.DataSource) ctx.lookup("java:comp/env/jdbc/ReportsDB");
        } catch (javax.naming.NamingException e) {
            throw new SQLException("DataSource lookup failed", e);
        }
    }
}
